INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'at-b2g-2014', id, '2014-01-01', 1, 'https://www.erechnung.gv.at', 0, '[{"label": "e-Rechnung.gv.at (USP)", "url": "https://www.erechnung.gv.at"}]', NULL FROM countries WHERE code = 'AT';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2g-2014', 'en', 'Federal B2G e-invoicing mandate takes effect', 'The Republic of Austria stops accepting paper invoices from suppliers to federal government bodies (IKTKonG §5, BGBl. I Nr. 35/2012). Invoices must be submitted electronically, either in the ebInterface XML format or as UBL via Peppol — one of the earliest B2G mandates in the EU.', '["Register as a government supplier via the USP portal (erechnung.gv.at)", "Confirm your invoicing software supports ebInterface or Peppol BIS 3.0"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'at-b2g-extended-2018', id, '2018-01-01', 0, 'https://www.eu-einvoicing.com/news/austria-b2g-e-invoicing-guide-ebinterface-peppol-2026', 1, '[{"label": "e-Rechnung.gv.at (USP)", "url": "https://www.erechnung.gv.at"}]', NULL FROM countries WHERE code = 'AT';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2g-extended-2018', 'en', 'B2G mandate extended to all central contracting authorities', 'The Federal Public Procurement Act 2018 (BVergG 2018, §368) broadens the existing e-invoicing obligation beyond core federal ministries to cover all central contracting authorities. Several of Austria''s nine Länder (states) — including Vienna, Lower Austria, and Upper Austria — have since adopted comparable requirements of their own.', '["Check whether your specific contracting authority (federal, state, or municipal) has its own e-invoicing requirement", "Confirm ebInterface or Peppol coverage extends to the full range of public bodies you invoice"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'at-ebinterface-70', id, '2026-10-01', 0, 'https://www.wko.at/netzwerke/was-ist-ebinterface', 1, '[{"label": "WKO — ebInterface", "url": "https://www.wko.at/netzwerke/was-ist-ebinterface"}]', 'expected' FROM countries WHERE code = 'AT';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-ebinterface-70', 'en', 'ebInterface 7.0 due, with formal EN 16931 syntax binding', 'AUSTRIAPRO (the WKO''s e-billing working group) is preparing ebInterface 7.0 for release in Q4 2026, adding a formal syntax binding to the European e-invoicing standard EN 16931. No mandatory migration from 6.0/6.1 has been announced, and development is proceeding with backward compatibility in mind.', '["No action required yet — existing ebInterface 6.0/6.1 implementations remain valid", "Watch for the 7.0 release and any future guidance on adoption timing"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'at-b2b-proposal-2026', id, '2026-09-30', 0, 'https://www.vatupdate.com/2026/07/03/austria-e-invoicing-e-reporting-country-booklet/', 1, '[{"label": "e-Rechnung.gv.at (USP)", "url": "https://www.erechnung.gv.at"}]', 'expected' FROM countries WHERE code = 'AT';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-b2b-proposal-2026', 'en', 'Formal domestic B2B e-invoicing proposal expected', 'Austria has no domestic B2B e-invoicing or real-time reporting mandate today — B2B structured invoicing remains voluntary, though widely adopted, especially among businesses with EU trading partners already under mandatory regimes. The Finance Ministry (BMF) has signalled it will pursue a Peppol-based approach, mirroring Belgium and the Netherlands, with a formal proposal expected in Q3 2026 — not yet published as of early August 2026.', '["Track BMF and RIS (Rechtsinformationssystem) for the formal proposal once published", "If already Peppol-enabled for B2G, no additional infrastructure should be needed for an eventual B2B mandate"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'at-vida-2030', id, '2030-07-01', 0, 'https://www.vatupdate.com/2026/07/03/austria-e-invoicing-e-reporting-country-booklet/', 1, '[{"label": "e-Rechnung.gv.at (USP)", "url": "https://www.erechnung.gv.at"}]', NULL FROM countries WHERE code = 'AT';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('at-vida-2030', 'en', 'ViDA cross-border B2B digital reporting takes effect', 'Regardless of the outcome of any domestic B2B proposal, the EU''s VAT in the Digital Age (ViDA) directive requires structured e-invoicing and digital reporting for cross-border B2B transactions from 1 July 2030 — confirmed EU law (Council Directive (EU) 2025/516, OJEU 25 March 2025).', '["Any business trading cross-border within the EU should plan for EN 16931-compliant e-invoicing capability by this date regardless of Austria''s domestic timeline"]');
